{
  "graph_update": {
    "triple_operations": [
      {
        "type": "insert",
        "graph": {
          "@context": {
            "rdf": "http://www.w3.org/1999/02/22-rdf-syntax-ns#",
            "rdfs": "http://www.w3.org/2000/01/rdf-schema#",
            "owl": "http://www.w3.org/2002/07/owl#",
            "xsd": "http://www.w3.org/2001/XMLSchema#",
            "schema": "https://schema.org/",
            "cd": "https://growgraph.dev/facts/",
            "seed": "https://github.com/dahrb/Art_6/tree/main/ontology/seed.ttl#",
            "foaf": "http://xmlns.com/foaf/0.1/"
          },
          "@graph": [
            {
              "@id": "seed:CaseDocument",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Case Document",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Document produced within or about judicial proceedings (judgments, decisions, press articles, filings). Used as source material for evidentiary claims such as bias allegations and for citation relations.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "foaf:Document"
              }
            },
            {
              "@id": "seed:DomesticProceeding",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Domestic Proceeding",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Proceeding before a domestic (national or constitutional) court; parent class for hearings, recusal challenges, citizenship reviews and constitutional findings.",
                "@language": "en"
              },
              "rdfs:subClassOf": [
                {
                  "@id": "seed:ProceduralStage"
                },
                {
                  "@id": "schema:Event"
                }
              ]
            },
            {
              "@id": "seed:LegalFinding",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Legal Finding",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Abstract class for determinations of law made by a court (e.g., incompatibility findings, conclusions on statutory conformity). Serves as the parent for specialized findings such as ConstitutionalIncompatibilityFinding.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:Article6Limb",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Article 6 Limb",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Abstract class representing the procedural limb of Article 6 (e.g., civil, criminal, constitutional, mixed). Specific limb values are modelled as subclasses.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:ImportanceLevel",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Importance Level",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Abstract classification of the importance or precedential weight of a judgment (e.g., key case, important case, report, little interest). Specific values are modelled as subclasses.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:Gender",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Gender",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Controlled vocabulary class for gender values (Male, Female, Non-binary, Unknown). Specific controlled values are modelled as subclasses.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:LawSystem",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Law System",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Abstract class grouping jurisdictional law-system types (e.g., common law, civil law, mixed).",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:ChamberType",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Chamber Type",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Abstract class for types of court formations (Chamber, Committee, Grand Chamber, Commission). Specific formations are modelled as subclasses.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "owl:Thing"
              }
            },
            {
              "@id": "seed:OperativeProvision",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Operative Provision",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Statutory or regulatory provision that is operative in a decision; target class for remedies (seed:hasRemedy domain).",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "seed:Law"
              }
            },
            {
              "@id": "seed:ConventionArticle",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "Convention/Constitution Article",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Class representing an article or paragraph of a constitution or convention used as citation targets for incompatibility findings.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "seed:Law"
              }
            },
            {
              "@id": "seed:PresidentOfConstitutionalCourt",
              "@type": "owl:Class",
              "rdfs:label": {
                "@value": "President of the Constitutional Court",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Role-specific class for the presiding judge/officer of a constitutional court; subclass of seed:Judge to permit procedural relations like challenges and appointments.",
                "@language": "en"
              },
              "rdfs:subClassOf": {
                "@id": "seed:Judge"
              }
            },
            {
              "@id": "seed:relatesToProceeding",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "relates To Proceeding",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Links a procedural challenge (recusal) to the domestic proceeding or case it concerns (e.g., case no. 40/03).",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "seed:RecusalChallenge"
              },
              "rdfs:range": {
                "@id": "seed:DomesticProceeding"
              }
            },
            {
              "@id": "seed:recommendedBy",
              "@type": "owl:ObjectProperty",
              "rdfs:label": {
                "@value": "recommended By",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Links a CitizenshipStatusReview or similar recommendation to the Commission or body that made the recommendation.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "seed:CitizenshipStatusReview"
              },
              "rdfs:range": {
                "@id": "seed:Commission"
              }
            },
            {
              "@id": "seed:hasDecisionDate",
              "@type": "owl:DatatypeProperty",
              "rdfs:label": {
                "@value": "has Decision Date",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Date on which a decision or ruling was issued (used for domestic case documents).",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "seed:CaseDocument"
              },
              "rdfs:range": {
                "@id": "xsd:date"
              }
            },
            {
              "@id": "seed:hasJudgmentDate",
              "@type": "owl:DatatypeProperty",
              "rdfs:label": {
                "@value": "has Judgment Date",
                "@language": "en"
              },
              "rdfs:comment": {
                "@value": "Date on which a judgment was handed down; recorded on case documents or judgment records.",
                "@language": "en"
              },
              "rdfs:domain": {
                "@id": "seed:CaseDocument"
              },
              "rdfs:range": {
                "@id": "xsd:date"
              }
            }
          ]
        }
      ]
    }
  }
}
